    if bias is None and len(inputs) > 2:
        bias = inputs[2]

    batched = x.dim() == 4
    if batched:
        b, cin, h, w = x.shape
    else:
        cin, h, w = x.shape
    cout, kh, kw = weight.shape[1], weight.shape[2], weight.shape[3]

    stride = getattr(module, 'stride', None)
    if isinstance(stride, (tuple, list)):
        stride = stride[0]
    if not stride:
        stride = kh
    padding = getattr(module, 'padding', 0)
    if isinstance(padding, (tuple, list)):
        padding = padding[0]

    # Step 1: flatten_input -> spatial-major rows [h*w, cin]
    if batched:
        xm = x.reshape(cin, h * w).t().contiguous()
    else:
        xm = x.permute(1, 2, 0).reshape(h * w, cin).contiguous()

    # Step 2: gemm rows @ weight flattened [cin, cout*kh*kw]
    w2 = weight.reshape(cin, cout * kh * kw)
    prod = xm @ w2  # [h*w, cout*kh*kw]

    # Step 3: tile_scatter -> [cout, h*stride, w*stride]
    prod = prod.reshape(h, w, cout, kh, kw).permute(2, 0, 3, 1, 4).contiguous()
    out = prod.reshape(cout, h * stride, w * stride)

    # Step 4: add_bias
    if bias is not None:
        out = out + bias.reshape(1, cout, 1, 1)
    if batched:
        out = out.unsqueeze(0)
    return out

